'use client'

import { useState } from 'react'

// ── 画像データ（テンプレートExcelより抽出） ─────────────────────
const LOGO_SRC = 'data:image/png;base64,'
const QR_SRC   = 'data:image/jpeg;base64,'

// ── 令和年号変換 ────────────────────────────────────────
function getReiwaDate(): string {
  const d = new Date()
  const reiwa = d.getFullYear() - 2018
  const month = d.getMonth() + 1
  return `令和${reiwa}年${month}月吉日`
}

// ── 編集可能インラインテキスト ──────────────────────────
function CE({
  value, onChange, style, placeholder,
}: {
  value: string
  onChange: (v: string) => void
  style?: React.CSSProperties
  placeholder?: string
}) {
  return (
    <span
      contentEditable
      suppressContentEditableWarning
      onInput={e => onChange((e.target as HTMLSpanElement).innerText)}
      data-placeholder={placeholder}
      style={{ outline: 'none', display: 'inline', borderRadius: 2, padding: '1px 2px', ...style }}
    >
      {value}
    </span>
  )
}

// ── メインコンポーネント ────────────────────────────────
